252	/**
253	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
254	 * so tests can assert side-effects by reading that file — the second test-assertion channel
255	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
256	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
257	 *
258	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
259	 * SYNC) so a test reads the record immediately.
260	 */
261	@Service
262	public class Audit {
263	
264	    private final Path file;
265	
266	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
267	        this.file = Path.of(path);
268	    }
269	
270	    /** Append one audit record. Tests assert the exact line(s) in the file. */
271	    public synchronized void record(String entry) {
272	        try {
273	            Path parent = file.toAbsolutePath().getParent();
274	            if (parent != null) {
275	                Files.createDirectories(parent);
276	            }
277	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
278	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
279	        } catch (IOException e) {
280	            throw new UncheckedIOException(e);
281	        }
282	    }
283	
284	    /** Truncate the audit file (called by /__test__/reset for per-spec isolation). */
285	    public synchronized void clear() {
286	        try {
287	            Files.deleteIfExists(file);
288	        } catch (IOException e) {
289	            throw new UncheckedIOException(e);
290	        }
