                            new BigDecimal(l.get("qty").toString()), new BigDecimal(l.get("unitPrice").toString()));
                } else {
                    jdbc.update("INSERT INTO invoice_line_item (invoice_id, description, qty, unit_price)"
                            + " VALUES (?, ?, ?, ?)",
